    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(supplyAmount > 0, "need positive supply");
        require(address(this).balance == 0, "no unsolicited ether");
        require(redeemAmount <= supplyAmount, "redeem not more than supplied");

        IERC20 mAsset = IERC20(c.depositToken());
        mAsset.approve(address(c), supplyAmount);

        c.supplyTokenTo(supplyAmount, address(this));

        uint256 balanceBefore = mAsset.balanceOf(address(this));
        uint256 credited = c.imBalances(address(this));
        uint256 exchangeRate = c.savings().exchangeRate();
        uint256 representedValue = credited * exchangeRate / 1e18;
        require(representedValue >= redeemAmount, "credit cannot cover redeem");

        bool reverted;
        try c.redeemToken(redeemAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = mAsset.balanceOf(address(this));

        assert(!reverted && balanceAfter - balanceBefore >= redeemAmount);
    }

    receive() external payable {}
}

