contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(supplyAmount > 0);
        require(redeemAmount > 0);

        address user = address(0xBEEF);
        address mAsset = c.depositToken();

        uint256 testBalanceBefore = IERC20(mAsset).balanceOf(address(this));

        IERC20(mAsset).approve(address(c), supplyAmount);
        c.supplyTokenTo(supplyAmount, user);

        uint256 credits = c.imBalances(user);
        require(credits > 0);

        uint256 userBalanceBefore = IERC20(mAsset).balanceOf(user);
        uint256 testBalanceBeforeRedeem = IERC20(mAsset).balanceOf(address(this));

        uint256 creditsBefore = c.imBalances(user);

        bool reverted;
        try c.redeemToken(redeemAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.imBalances(user) == creditsBefore);
            assert(IERC20(mAsset).balanceOf(user) == userBalanceBefore);
            assert(IERC20(mAsset).balanceOf(address(this)) == testBalanceBeforeRedeem);
        } else {
            uint256 creditsAfter = c.imBalances(user);
            assert(creditsAfter <= creditsBefore);
            assert(IERC20(mAsset).balanceOf(address(this)) <= testBalanceBeforeRedeem);
        }
    }

    receive() external payable {}
}

