contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount, address to) public payable {
        require(to != address(0), "beneficiary must be nonzero");
        uint256 creditsBefore = c.savings().creditBalances(address(c));
        bool supplied = false;
        try c.supplyTokenTo(amount, to) {
            supplied = true;
        } catch {
            supplied = false;
        }
        uint256 creditsAfter = c.savings().creditBalances(address(c));
        uint256 toBal = c.imBalances(to);
        bool ok;
        if (supplied) {
            ok = creditsAfter >= creditsBefore && toBal <= creditsAfter - creditsBefore;
        } else {
            ok = creditsAfter == creditsBefore && toBal == 0;
        }
        assert(ok);
    }
    receive() external payable {}
}

