        uint256 balBefore = c.balanceOfToken(beneficiary);

        c.supplyTokenTo(supplyAmount, beneficiary);

        uint256 balAfterSupply = c.balanceOfToken(beneficiary);
        uint256 rateAfter = 1e18;

        uint256 redeemActual;
        bool redeemReverted;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            redeemActual = actual;
            redeemReverted = false;
