        // General rule: the credited balance of the beneficiary must reflect exactly
        // the mAsset amount supplied (exchange rate is 1e18), and after a redeem the
        // balance must decrease (or stay the same if the redeem failed).
        if (redeemReverted) {
            assert(balAfterRedeem == balAfterSupply);
        } else {
            assert(balAfterRedeem <= balAfterSupply);
            assert(balAfterRedeem + (redeemActual * rateAfter) / 1e18 >= balAfterSupply);
        }

        // The net credited balance should never exceed the total supplied amount.
        assert(balAfterRedeem <= balBefore + supplyAmount);
    }

    receive() external payable {}
}

