            uint256 expectedBalance = (afterCredits * rate) / 1e18;
            uint256 actualBalance = c.balanceOfToken(user);
            assert(actualBalance == expectedBalance);
            assert(afterCredits >= beforeCredits);
        }
    }

    receive() external payable {}
}

