contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount, address to, address redeemer) public payable {
        require(to != address(0), "to");
        require(redeemer != address(0), "redeemer");

        supplyAmount = supplyAmount % 1_000_000e18 + 1;
        redeemAmount = redeemAmount % 1_000_000e18 + 1;

        // Ensure this test contract holds enough of the deposit token and can approve mAsset.
        uint256 testBalance = c.mAsset().balanceOf(address(this));
        require(testBalance >= supplyAmount, "in test token balance");
        c.mAsset().approve(address(c), supplyAmount);

        // Supply into the yield source for the redeemer.
        c.supplyTokenTo(supplyAmount, redeemer);

        uint256 beforeCredits = c.imBalances(redeemer);
        uint256 beforeToken = c.mAsset().balanceOf(address(this));

        // The redeeming caller is this test contract, not necessarily `redeemer`.
        // Only run the eligibility check/solvent redemption when msg.sender has credits.
        uint256 senderCredits = c.imBalances(address(this));
        if (senderCredits == 0) {
            // Nothing held by this test contract yet; first credit it a small eligible amount.
            c.supplyTokenTo(supplyAmount, address(this));
            senderCredits = c.imBalances(address(this));
        }

        uint256 creditsToRedeem = redeemAmount % senderCredits + 1;

        uint256 balanceBeforeRedeem = c.mAsset().balanceOf(address(this));
        uint256 creditsBeforeRedeem = c.imBalances(address(this));

        bool reverted;
        uint256 actualOut;
        try c.redeemToken(creditsToRedeem) returns (uint256 out) {
            actualOut = out;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditsAfterRedeem = c.imBalances(address(this));
        uint256 balanceAfterRedeem = c.mAsset().balanceOf(address(this));

        if (reverted) {
            assert(creditsAfterRedeem == creditsBeforeRedeem && balanceAfterRedeem == balanceBeforeRedeem);
        } else {
            assert(creditsAfterRedeem == creditsBeforeRedeem - creditsToRedeem);
            assert(balanceAfterRedeem == balanceBeforeRedeem + actualOut);
            assert(actualOut > 0);
        }

        // General invariant: the redeemer's credit balance is still consistent with total supplied/credited.
        assert(c.imBalances(redeemer) <= beforeCredits);
        assert(c.balanceOfToken(address(this)) >= 0);
        assert(c.balanceOfToken(redeemer) <= beforeCredits);
    }

    receive() external payable {}
}

