    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0);

        address mAssetAddr = c.depositToken();
        uint256 cBalanceBefore = IERC20(mAssetAddr).balanceOf(address(c));

        bool reverted;
        uint256 actual;
        try c.redeemToken(amount) returns (uint256 a) {
            actual = a;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = IERC20(mAssetAddr).balanceOf(address(c));

        assert(!reverted || cBalanceAfter == cBalanceBefore);
    }

    receive() external payable {}
}

