contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "zero address not allowed");
        require(mAssetAmount > 0, "amount must be positive");

        IERC20 mAsset = c.mAsset();
        ISavingsContractV2 savings = c.savings();

        uint256 balBefore = mAsset.balanceOf(address(this));
        require(balBefore >= mAssetAmount, "insufficient balance for supply");
        require(mAsset.approve(address(c), mAssetAmount), "approve failed");

        uint256 cAssetBefore = mAsset.balanceOf(address(c));
        uint256 exchangeRate = savings.exchangeRate();

        c.supplyTokenTo(mAssetAmount, to);

        uint256 imAfter = c.imBalances(to);
        uint256 cAssetAfter = mAsset.balanceOf(address(c));
        uint256 expectedIm = (mAssetAmount * 1e18) / exchangeRate;

        assert(cAssetAfter == cAssetBefore + mAssetAmount);
        assert(imAfter == expectedIm);
    }

    receive() external payable {}
}

