contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 redeemAmount, address to) public payable {
        require(to != address(0), "bad beneficiary");
        require(depositAmount > 0, "zero deposit");
        require(redeemAmount > 0, "zero redeem");

        address cAddr = address(c);
        uint256 cBalBefore = IERC20(c.mAsset()).balanceOf(cAddr);
        uint256 creditsBefore = c.imBalances(address(this));

        // Fund this test contract with enough mAsset to supply.
        require(IERC20(c.mAsset()).balanceOf(address(this)) >= depositAmount, "insufficient funds");
        IERC20(c.mAsset()).approve(cAddr, depositAmount);

        try c.supplyTokenTo(depositAmount, address(this)) {
            // expected credits issued on supply; supplyTokenTo gives credits to `to`.
            // We only validate the redeem path below, so this branch only sets baseline through state.
        } catch {
            // If supply fails, the redeem-based rule below is not reachable; we just assert on state consistency.
        }

        uint256 creditsAfterSupply = c.imBalances(address(this));
        uint256 cBalAfterSupply = IERC20(c.mAsset()).balanceOf(cAddr);

        // Now attempt the redeem call; capture the reported actual mAsset returned.
        bool redeemReverted;
        uint256 reportedActual;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            redeemReverted = false;
            reportedActual = actual;
        } catch {
            redeemReverted = true;
        }

        uint256 creditsAfterRedeem = c.imBalances(address(this));
        uint256 cBalAfterRedeem = IERC20(c.mAsset()).balanceOf(cAddr);

        // If redeem succeeded, c's mAsset balance decreased by exactly the amount returned.
        // Reported actual must match the balance decrease, and the caller's credits must have
        // been reduced by the savings-authorized creditsBurned (observable via the credited amount).
        if (!redeemReverted) {
            assert(cBalAfterRedeem == cBalAfterSupply - reportedActual);
        } else {
            // On revert, c's state must not change: balances and credits unchanged.
            assert(cBalAfterRedeem == cBalAfterSupply && creditsAfterRedeem == creditsAfterSupply);
        }
    }

    receive() external payable {}
}

