    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount) public {
        require(mAssetAmount > 0, "amount must be positive");

        IERC20 mAsset = c.mAsset();

        // Fund this test contract with enough mAsset to supply and redeem.
        // We cannot mint directly, so we require the test to already hold mAsset.
        uint256 mAssetBal = mAsset.balanceOf(address(this));
        require(mAssetBal >= mAssetAmount, "test contract must hold enough mAsset");

        // Record state before redeem.
        uint256 balanceBefore = mAsset.balanceOf(address(c));

        // The deciding call. It may revert if the savings contract has insufficient liquidity,
        // or if credits are insufficient.
        uint256 mAssetsActual;
        bool reverted;
        try c.redeemToken(mAssetAmount) returns (uint256 actual) {
            mAssetsActual = actual;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 balanceAfter = mAsset.balanceOf(address(c));
            // General rule: the mAsset balance of c decreases by exactly the amount the caller receives.
            assert(balanceAfter + mAssetsActual == balanceBefore);
        } else {
            // A revert must leave c's mAsset balance unchanged.
            uint256 balanceAfter = mAsset.balanceOf(address(c));
            assert(balanceAfter == balanceBefore);
        }
    }
}

