contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public {
        require(supplyAmount > 0, "supply zero");
        require(redeemAmount > 0, "redeem zero");

        // Give this test contract enough mAsset and approve c to pull it.
        address mAssetAddr = c.depositToken();
        IERC20 mAsset = IERC20(mAssetAddr);

        uint256 bal = mAsset.balanceOf(address(this));
        require(bal >= supplyAmount, "not enough mAsset for supply");

        mAsset.approve(address(c), supplyAmount);

        // Supply to this contract so the same address can later redeem.
        c.supplyTokenTo(supplyAmount, address(this));

        // Read created state through c's public/external surface.
        uint256 creditsBefore = c.imBalances(address(this));
        uint256 mAssetBalanceBefore = mAsset.balanceOf(address(this));

        // Attempt the redeem. It may revert for too large an amount.
        bool reverted;
        uint256 mAssetsActual;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            reverted = false;
            mAssetsActual = actual;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 creditsAfter = c.imBalances(address(this));
            uint256 mAssetBalanceAfter = mAsset.balanceOf(address(this));

            // General rule: on a successful redeem, the caller's credit balance decreases and
            // the received amount equals the contract's reported actual amount and the balance increase.
            assert(
                creditsAfter <= creditsBefore &&
                mAssetsActual == mAssetBalanceAfter - mAssetBalanceBefore &&
                mAssetBalanceAfter > mAssetBalanceBefore
            );
        } else {
            // If it reverts, state must be unchanged (nonReentrant + revert atomicity).
            uint256 creditsAfter = c.imBalances(address(this));
            uint256 mAssetBalanceAfter = mAsset.balanceOf(address(this));
            assert(creditsAfter == creditsBefore && mAssetBalanceAfter == mAssetBalanceBefore);
        }
    }

    receive() external payable {}
}

