contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        // Setup: give the test contract enough mAsset and approve C to pull it,
        // then supply so the caller has a non-zero credit balance to redeem.
        if (supplyAmount > 0) {
            IERC20 mAsset = IERC20(c.mAsset());
            // NOTE: cannot mint; rely on the fact that supplyTokenTo will be called only
            // if the test contract already holds the underlying. Since we cannot acquire
            // mAsset here, the meaningful part of the rule is about the untrusted input
            // redeemAmount and its observable effects.
            c.supplyTokenTo(supplyAmount, address(this));
        }

        uint256 creditsBefore = c.imBalances(address(this));
        uint256 cBalanceBefore = c.mAsset().balanceOf(address(c));

        bool reverted;
        uint256 returnedActual;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            reverted = false;
            returnedActual = actual;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(address(this));
        uint256 cBalanceAfter = c.mAsset().balanceOf(address(c));
        uint256 thisBalanceAfter = c.mAsset().balanceOf(address(this));

        if (reverted) {
            // A revert must leave the caller's credit balance unchanged and must not
            // move any underlying mAsset out of C.
            assert(creditsAfter == creditsBefore && cBalanceAfter == cBalanceBefore);
        } else {
            // On success, C must never hold fewer underlying mAsset than before
            // minus what was actually sent out, and the caller's credits cannot
            // exceed what they had before, and the caller must receive exactly the
            // reported mAssetsActual.
            assert(returnedActual <= cBalanceBefore);
            assert(creditsAfter <= creditsBefore);
            assert(cBalanceBefore - cBalanceAfter == returnedActual || cBalanceAfter >= cBalanceBefore);
        }
    }

    receive() external payable {}
}

