contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public {
        require(supplyAmount > 0, "supplyAmount must be positive");
        require(redeemAmount > 0, "redeemAmount must be positive");

        uint256 creditsBefore = c.imBalances(address(this));

        // supply to this test contract
        c.supplyTokenTo(supplyAmount, address(this));

        uint256 creditsAfterSupply = c.imBalances(address(this));
        require(creditsAfterSupply >= creditsBefore, "credits decreased after supply");
        uint256 issuedCredits = creditsAfterSupply - creditsBefore;

        // redeem a separate amount, but this must not require more credits than issued
        // unless the user already had enough balance; we use fresh sender so credits before should be 0
        // However, the contract allows any caller and its own balances are shared; to make the rule general,
        // supply first, then redeem the full amount. We use redeemAmount independent, but for the property
        // we want to show that after supplying, redeeming the same amount will succeed (if enough balance).
        // The general rule: after supplying `supplyAmount`, calling redeemToken with at most that amount
        // must not revert due to subtraction underflow (i.e. must not burn more credits than held).
        // We must ensure supplyAmount is the amount actually supplied, so redeemAmount <= supplyAmount.
        // To make it a general rule we restrict redeemAmount to be <= supplyAmount.
        // This is a precondition, not part of the property.
        require(redeemAmount <= supplyAmount, "redeemAmount must not exceed supplyAmount");

        uint256 mAssetBalanceBefore = c.mAsset().balanceOf(address(this));

        bool reverted;
        uint256 actualRedeemed;
        try c.redeemToken(redeemAmount) returns (uint256 _actual) {
            reverted = false;
            actualRedeemed = _actual;
        } catch {
            reverted = true;
        }

        uint256 creditsAfterRedeem = c.imBalances(address(this));
        uint256 mAssetBalanceAfter = c.mAsset().balanceOf(address(this));

        // General rule: the redeem either reverts, or it succeeds and burns credits.
        // If it succeeds, it must not have burned more credits than were issued (issuedCredits) and
        // the test contract must have received the redeemed mAssets.
        // We express this without subtraction underflow: if creditsAfterRedeem <= creditsAfterSupply,
        // then creditsBurned = creditsAfterSupply - creditsAfterRedeem.
        // We assert: reverted || (creditsAfterRedeem <= creditsAfterSupply && actualRedeemed > 0 && mAssetBalanceAfter >= mAssetBalanceBefore + actualRedeemed)
        // However, if the user had pre-existing balance, creditsBefore > 0, the redeem may burn from that.
        // Our test runs once, so creditsBefore is 0 for this test contract. That is fine: the rule is general
        // for the sequence where the caller has no prior balance? But the checker may call with any params and
        // this test contract may have received tokens from elsewhere? No, fresh deployment, only this run.
        // So creditsBefore is always 0 for the first supply. However, if the checker runs this multiple times?
        // The specification says runs once. So creditsBefore == 0 initially. But to be safe, we compute issuedCredits.
        // After redeem, the credits burned = creditsAfterSupply - creditsAfterRedeem (if no underflow).
        // We also expect that the redeemed amount is at most the supplied amount, and the mAsset balance increases by actualRedeemed.
        // The key invariant: the contract must not allow redeeming more credits than the user has, which would underflow.
        // So if redeemAmount <= supplyAmount, the redeem must succeed (assuming enough liquidity) and burn credits <= issuedCredits.
        // We assert: reverted || (creditsAfterRedeem <= creditsAfterSupply && actualRedeemed > 0 && mAssetBalanceAfter >= mAssetBalanceBefore + actualRedeemed)
        // But we need to ensure the revert is not due to something else. The precondition is that redeemAmount <= supplyAmount,
        // but the contract might still revert if the savings contract doesn't have enough underlying. That's external.
        // However, the rule is about the contract's own accounting: it must not revert due to underflow in imBalances subtraction.
        // So we assert: if reverted, then the credits balance must not have changed (i.e., no partial state change), else it succeeded.
        // But reentrancy guard and state changes: if it reverts, the whole transaction reverts, so we can't observe state after revert.
        // Actually, a revert in a try/catch does not revert the outer transaction, but the state changes made in the inner call are reverted.
        // So after a caught revert, creditsAfterRedeem == creditsAfterSupply (no change) if the inner call reverted.
        // However, the ERC20 transfer might have happened before the revert? No, revert rolls back all state changes of the inner call.
        // So after a revert, the credits and mAsset balances should be unchanged from before the redeem call.
        // But we read mAssetBalanceBefore before the redeem, and after the revert it should be the same.
        // So we assert: if reverted, then creditsAfterRedeem == creditsAfterSupply and mAssetBalanceAfter == mAssetBalanceBefore.
        // If not reverted, then creditsAfterRedeem <= creditsAfterSupply, actualRedeemed > 0, and mAssetBalanceAfter >= mAssetBalanceBefore + actualRedeemed.

        assert(
            reverted
                ? (creditsAfterRedeem == creditsAfterSupply && mAssetBalanceAfter == mAssetBalanceBefore)
                : (creditsAfterRedeem <= creditsAfterSupply &&
                    actualRedeemed > 0 &&
                    mAssetBalanceAfter >= mAssetBalanceBefore &&
                    mAssetBalanceAfter - mAssetBalanceBefore == actualRedeemed &&
                    creditsAfterRedeem >= creditsAfterSupply - issuedCredits)
        );
    }

    receive() external payable {}
}

