        uint256 mAssetFinal = IERC20(c.depositToken()).balanceOf(me);
        uint256 contractFinal = IERC20(c.depositToken()).balanceOf(address(c));

        assert(
            reverted
                ? (creditsFinal == creditsAfterDeposit && mAssetFinal == mAssetBefore && contractFinal == contractBefore)
                : (creditsBefore == 0 && creditsAfterDeposit == 0 && creditsFinal == 0)
                    || (mAssetFinal - mAssetBefore == actual && contractBefore - contractFinal == actual)
        );
    }
