contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 supplyAmount, uint256 redeemAmount) public {
        require(supplyAmount > 0 && redeemAmount > 0, "need nonzero amounts");
        require(redeemAmount <= supplyAmount, "redeem must not exceed supply");

        address mAssetAddr = c.depositToken();
        IERC20 mAsset = IERC20(mAssetAddr);

        // Fund the test contract with mAsset so it can call supplyTokenTo.
        // Use a low-level call to the mAsset's public/external surface; we only use
        // the return data presence, not any storage internals.
        (bool ok, bytes memory ret) = mAssetAddr.call(
            abi.encodeWithSelector(IERC20.transfer.selector, address(this), supplyAmount)
        );
        require(ok && (ret.length == 0 || abi.decode(ret, (bool))), "funding failed");

        // Approve c to pull the mAssets.
        (ok, ret) = mAssetAddr.call(
            abi.encodeWithSelector(IERC20.approve.selector, address(c), supplyAmount)
        );
        require(ok && (ret.length == 0 || abi.decode(ret, (bool))), "approve failed");

        uint256 mAssetBalBeforeSupply = mAsset.balanceOf(address(this));
        c.supplyTokenTo(supplyAmount, address(this));
        uint256 mAssetBalAfterSupply = mAsset.balanceOf(address(this));

        uint256 balOfTokenBefore = c.balanceOfToken(address(this));
        uint256 creditBefore = c.imBalances(address(this));

        uint256 mAssetBalBeforeRedeem = mAsset.balanceOf(address(this));

        bool reverted;
        uint256 actualReturned;
        try c.redeemToken(redeemAmount) returns (uint256 r) {
            reverted = false;
            actualReturned = r;
        } catch {
            reverted = true;
        }

        uint256 mAssetBalAfterRedeem = mAsset.balanceOf(address(this));
        uint256 balOfTokenAfter = c.balanceOfToken(address(this));
        uint256 creditAfter = c.imBalances(address(this));

        assert(
            !reverted &&
            actualReturned <= redeemAmount &&
            mAssetBalAfterRedeem - mAssetBalBeforeRedeem == actualReturned &&
            creditAfter < creditBefore &&
            balOfTokenAfter <= balOfTokenBefore
        );
    }

    receive() external payable {}
}

