        // to the before value), which is trivially true if the call reverted
        // (state rollback) and is the general rule being asserted: a failed
        // redemption leaves the user's credits untouched.
        assert(c.imBalances(address(this)) == creditsBefore);
    }

    receive() external payable {}
}

