        uint256 callerCreditsBefore = c.imBalances(address(this));

        c.supplyTokenTo(supplyAmount, to);

        uint256 toCreditsAfterSupply = c.imBalances(to);
        uint256 callerCreditsAfterSupply = c.imBalances(address(this));

        uint256 toCreditsAfterRedeem;
        uint256 callerCreditsAfterRedeem;
        bool reverted;

        try c.redeemToken(redeemAmount) returns (uint256 mAssetsActual) {
            reverted = false;
            require(mAssetsActual <= redeemAmount, "payout cannot exceed requested amount");
        } catch {
            reverted = true;
        }

        toCreditsAfterRedeem = c.imBalances(to);
        callerCreditsAfterRedeem = c.imBalances(address(this));

        assert(
            (reverted && toCreditsAfterRedeem == toCreditsAfterSupply && callerCreditsAfterRedeem == callerCreditsAfterSupply) ||
            (!reverted && toCreditsAfterRedeem >= toCreditsBefore && callerCreditsAfterRedeem <= callerCreditsAfterSupply)
        );
    }

