contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address to) public payable {
        require(to != address(0), "bad beneficiary");
        require(amount > 0, "zero amount");
        require(address(c.mAsset()).balanceOf(address(this)) >= amount, "insufficient mAsset");

        c.mAsset().approve(address(c), amount);

        uint256 rateBefore = c.savings().exchangeRate();
        uint256 creditsBefore = c.imBalances(to);

        uint256 supplyReverted;
        try c.supplyTokenTo(amount, to) {
            supplyReverted = 0;
        } catch {
            supplyReverted = 1;
        }

        uint256 creditsAfter = c.imBalances(to);
        uint256 rateAfter = c.savings().exchangeRate();

        uint256 deltaCredits = creditsAfter - creditsBefore;
        uint256 expectedMin = (amount * rateBefore) / 1e18;

        assert(
            supplyReverted == 0 &&
            (rateAfter == rateBefore
                ? deltaCredits == expectedMin
                : deltaCredits >= expectedMin)
        );
    }

    receive() external payable {}
}

