contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amountToSupply, uint256 amountToRedeem) public payable {
        require(amountToSupply > 0);
        require(amountToRedeem > 0);

        address depositor = address(this);

        // give this contract the mAsset tokens needed for supplyTokenTo
        IERC20 m = c.mAsset();
        uint256 mintAmount = amountToSupply;
        m.transferFrom(msg.sender, address(this), mintAmount);

        // deposit tokens into the savings contract on behalf of this contract
        c.supplyTokenTo(amountToSupply, depositor);

        uint256 creditsBefore = c.imBalances(depositor);
        require(creditsBefore > 0);

        uint256 exchangeRate = c.savings().exchangeRate();
        require(exchangeRate > 0);

        // compute the exact underlying amount corresponding to creditsBefore,
        // to avoid underflow when redeeming at least that many credits
        uint256 redeemableUnderlying = (creditsBefore * exchangeRate) / 1e18;
        require(redeemableUnderlying > 0);

        uint256 redeemAmount = amountToRedeem < redeemableUnderlying ? amountToRedeem : redeemableUnderlying;
        require(redeemAmount > 0);

        uint256 mAssetBalanceBefore = m.balanceOf(address(c));

        uint256 actual = c.redeemToken(redeemAmount);

        uint256 mAssetBalanceAfter = m.balanceOf(address(c));
        uint256 creditsAfter = c.imBalances(depositor);

        assert(
            creditsAfter < creditsBefore &&
            actual <= mAssetBalanceBefore + actual &&
            mAssetBalanceAfter == mAssetBalanceBefore + actual - actual
        );
    }

    receive() external payable {}
}

